  "devEnv.warningBodySrt": "The AI can run any program on the team server, in any chat. A command can read every team folder that the person of the chat can read. It can write only the project folder of the chat and that person's own folder. A sandbox hides the server's data, its secrets, other people's personal folders and the folders that person cannot open.\n- A command can send data out through the allowed sites. GitHub, npm and PyPI accept uploads, so a command can send every file that the person can read.\n- Each person can allow more sites for their own commands when a chat asks, or turn on Full internet for themselves. A command of that person can then send data to those sites too. No admin step is needed.\n- A command can copy a file that the person can read into the project folder, where more people can see it.\n- Files that a command changes in the person's own folder have no change record and no older versions.\n- Everyone who can write the project folder uses the same folder. A change by one person affects the next command of another person.\n- There are no logins. Do git push and similar commands on your own computer.\n- A run that uses too much memory stops. Heavy jobs of the team wait in a queue.\n- Commands are kept in the activity log.\nThis feature is an experiment and can be turned off at any time.",
