  'speech.mediaTranscripts': "Turn video sound into text",
  'speech.mediaTranscriptsLocal': "When the AI reads a video or audio file (a meeting recording, for example), this server turns its sound into text. The sound never leaves the server. It works in pieces of {sec, plural, one {# second} other {# seconds}}: one read turns as much as fits in its time, and reading again goes on from there.",
  'speech.mediaTranscriptsSmall': "Off by default: this server has {cores, plural, one {# CPU core} other {# CPU cores}}, so turning sound into text takes long. An admin can turn it on; while it is off the AI still sees a video's frames.",
  'speech.mediaTranscriptsSpeedMin': "Measured on this server: about {n, plural, one {# minute} other {# minutes}} for each minute of sound.",
  'speech.mediaTranscriptsSpeedSec': "Measured on this server: about {n, plural, one {# second} other {# seconds}} for each minute of sound.",
  'speech.mediaTranscriptsHosted': "On this hosted server one read turns at most {min, plural, one {# minute} other {# minutes}} of new sound into text.",
  'speech.mediaTranscriptsOpenRouter': "When the AI reads a video or audio file (meeting recordings, customer calls, training videos), its sound goes to OpenRouter and its provider to be turned into text. This is other material than voice input. Zero data retention is requested, but we cannot enforce it. Nothing is sent from confidential chats.",
  'speech.privacy': "Audio is sent to OpenRouter and its provider; zero data retention is requested.",
  'speech.model': "Model",
  'speech.key': "OpenRouter API key",
  'speech.keySet': "A key is set (…{hint}).",
  'speech.keyNone': "No key yet. Voice input stays off until a key is added.",
