  'speech.price': "OpenRouter costs about $0.1 per hour of recording.",
  'speech.saveKey': "Save key",
  'speech.removeKey': "Remove key",
  'speech.removeConfirm': "Remove the OpenRouter key? Voice input stops until a new key is added.",
  'speech.keySaved': "Key saved",
  'speech.keyRemoved': "Key removed",
  'speech.mediaTranscriptsHostedKey': "When the AI reads a video or audio file (a meeting recording, say), Trina's hosted transcription turns its sound into text: it goes through OpenRouter to DeepInfra in the US (Groq if DeepInfra is down), and neither keeps the data. It uses the same free hours as voice input. Nothing is sent from a confidential chat.",
  'speech.privacyHosted': "Speech goes through OpenRouter to DeepInfra in the US (Groq if DeepInfra is down) to be turned into text, and only to providers that keep no data (zero data retention).",
  'speech.hostedKeyInUse': "Transcribing with the key Trina hosting provides. A team key you add is used first and has no time limit (OpenRouter bills the team's account).",
  'speech.hostedUsage': "This month: {used} of {free} free transcription hours used",
